SELECT *
FROM sensor_record
WHERE device_id = #{deviceId}
AND sensor_key = #{sensorKey}

    AND timestamp >= #{start}


    AND timestamp <= #{end}

ORDER BY timestamp DESC

SELECT *
FROM sensor_record
WHERE device_id = #{deviceId}
AND source = 'slave'
AND slave_address = #{slaveAddress}

    AND channel = #{channel}


    AND sensor_type = #{sensorType}


    AND timestamp >= #{start}


    AND timestamp <= #{end}

ORDER BY channel, timestamp DESC

SELECT AVG(sensor_value)
FROM sensor_record
WHERE device_id = #{deviceId}
AND sensor_key = #{sensorKey}

    AND timestamp >= #{start}


    AND timestamp <= #{end}
